cat > /etc/init.d/appsvc-web <<'APP_SVC_EOF'
#!/sbin/openrc-run

name="appsvc rootless web container"
description="Rootless nginx web application owned by appsvc"

uid="$(id -u appsvc)"
runtime_dir="/run/user/${uid}"
app_env="HOME=/home/appsvc XDG_RUNTIME_DIR=${runtime_dir}"

depend() {
    need cgroups
    after networking
}

start_pre() {
    checkpath -d -m 0700 -o appsvc:appsvc "${runtime_dir}"
}

start() {
    ebegin "Starting ${name}"
    su -s /bin/sh appsvc -c "${app_env} podman rm -f appsvc-web >/dev/null 2>&1 || true; ${app_env} podman run --name appsvc-web --detach --pull=never --restart=always --publish 0.0.0.0:8080:80 docker.io/library/nginx:alpine" >/dev/null
    eend $?
}

stop() {
    ebegin "Stopping ${name}"
    su -s /bin/sh appsvc -c "${app_env} podman stop --time 10 appsvc-web >/dev/null 2>&1 || true; ${app_env} podman rm -f appsvc-web >/dev/null 2>&1 || true"
    eend $?
}

status() {
    su -s /bin/sh appsvc -c "${app_env} podman inspect --format '{{.State.Status}}' appsvc-web" 2>/dev/null
}
APP_SVC_EOF
chmod 0755 /etc/init.d/appsvc-web
rc-update add appsvc-web default
rc-service appsvc-web start

